import{_ as i,C as c,o as n,c as h,j as d,a as t,E as o,a5 as a}from"./chunks/framework.BYIUCCsM.js";const P=JSON.parse('{"title":"树","description":"","frontmatter":{},"headers":[],"relativePath":"components/tree.md","filePath":"components/tree.md","lastUpdated":1787927919000}'),s={name:"components/tree.md"},b={id:"树",tabindex:"-1"};function p(g,e,u,x,f,m){const l=c("Badge"),r=c("XhDemo");return n(),h("div",null,[d("h1",b,[e[0]||(e[0]=t("树 ",-1)),o(l,{type:"info",text:"tree"}),e[1]||(e[1]=t()),e[2]||(e[2]=d("a",{class:"header-anchor",href:"#树","aria-label":'Permalink to "树 <Badge type="info" text="tree" />"'},"​",-1))]),e[3]||(e[3]=a('<p>层级数据的展开与选择：分支可展开，节点可选。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>文件目录、组织架构、权限节点这类任意深度的层级数据。</li><li>需要在树上多选并处理父子级联。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>树只是为了选一个值：用<a href="./tree-select">树选择</a>，它把树收进浮层。</li><li>层级规整、层数固定且只为选值：用<a href="./cascader">级联选择</a>。</li><li>数据是平的：用<a href="./list">列表</a>或<a href="./table">表格</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>展开集合与选中集合两套值各自可受控。</li><li><code>cascade</code> 与 <code>checkedStrategy</code> 决定勾父带不带子、以及回显给哪一层。</li><li>支持只让叶子进选中集合、关键词过滤、子节点异步加载、拖放换父。</li><li><code>expandOnClick</code> 决定点整行是否展开。</li><li><code>leafOrientation</code> 按结构判据横排：子节点全是叶子的那层跟着它走，其余恒竖排。</li><li>节点上标 <code>childrenOrientation: &#39;horizontal&#39; | &#39;vertical&#39;</code> 指定「我这一层子节点怎么排」， 比 <code>leafOrientation</code> 优先；标 <code>vertical</code> 能把树级的 <code>horizontal</code> 按回竖排。根层不受影响，恒竖排。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>collection 是层级元信息的唯一事实源，标记只管长相；缩进由子层容器自己顶着</p>',10)),o(r,{src:"tree/01-basic"}),e[4]||(e[4]=d("h3",{id:"多选",tabindex:"-1"},[t("多选 "),d("a",{class:"header-anchor",href:"#多选","aria-label":'Permalink to "多选"'},"​")],-1)),e[5]||(e[5]=d("p",null,"selectionMode 默认 single，改成 multiple 后点击与确认键都变成切换，选中集合形状不变仍是数组",-1)),o(r,{src:"tree/02-multiple"}),e[6]||(e[6]=d("h3",{id:"受控",tabindex:"-1"},[t("受控 "),d("a",{class:"header-anchor",href:"#受控","aria-label":'Permalink to "受控"'},"​")],-1)),e[7]||(e[7]=d("p",null,"传了 expandedValue / selection 就由宿主说了算，组件只发事件不落内部值，宿主写回它才动",-1)),o(r,{src:"tree/03-controlled"}),e[8]||(e[8]=d("h3",{id:"点行不展开与禁用节点",tabindex:"-1"},[t("点行不展开与禁用节点 "),d("a",{class:"header-anchor",href:"#点行不展开与禁用节点","aria-label":'Permalink to "点行不展开与禁用节点"'},"​")],-1)),e[9]||(e[9]=d("p",null,"expandOnClick 关掉后只有箭头与左右方向键能改展开态；禁用节点仍可聚焦，只是确认键不认它",-1)),o(r,{src:"tree/04-expand-on-click"}),e[10]||(e[10]=d("h3",{id:"关键词过滤",tabindex:"-1"},[t("关键词过滤 "),d("a",{class:"header-anchor",href:"#关键词过滤","aria-label":'Permalink to "关键词过滤"'},"​")],-1)),e[11]||(e[11]=d("p",null,"collection 换一份树就换一棵：标记跟着数据重铺，过滤剩下的分支顺手全展开",-1)),o(r,{src:"tree/05-filter"}),e[12]||(e[12]=d("h3",{id:"异步加载子节点",tabindex:"-1"},[t("异步加载子节点 "),d("a",{class:"header-anchor",href:"#异步加载子节点","aria-label":'Permalink to "异步加载子节点"'},"​")],-1)),e[13]||(e[13]=d("p",null,"展开那一刻才去要数据：先摆一行禁用的占位，取回来就地换掉，收起再展开不重复请求",-1)),o(r,{src:"tree/06-async"}),e[14]||(e[14]=d("h3",{id:"前缀与行尾",tabindex:"-1"},[t("前缀与行尾 "),d("a",{class:"header-anchor",href:"#前缀与行尾","aria-label":'Permalink to "前缀与行尾"'},"​")],-1)),e[15]||(e[15]=d("p",null,"行里放什么由标记说了算：文字前塞图标、文字后塞操作，方向指示也可以挪到行尾去",-1)),o(r,{src:"tree/07-prefix-suffix"}),e[16]||(e[16]=d("h3",{id:"只让叶子进选中集合",tabindex:"-1"},[t("只让叶子进选中集合 "),d("a",{class:"header-anchor",href:"#只让叶子进选中集合","aria-label":'Permalink to "只让叶子进选中集合"'},"​")],-1)),e[17]||(e[17]=d("p",null,"选中受控就由宿主定夺：分支的值直接不写回，点目录只剩展开收起这一个效果",-1)),o(r,{src:"tree/08-leaf-only"}),e[18]||(e[18]=d("h3",{id:"级联勾选",tabindex:"-1"},[t("级联勾选 "),d("a",{class:"header-anchor",href:"#级联勾选","aria-label":'Permalink to "级联勾选"'},"​")],-1)),e[19]||(e[19]=d("p",null,'selection-mode="multiple" 加 cascade 内建父子传导：点分支整枝勾上、子全勾父勾、部分勾中半选；勾选框是行里的一段标记，勾选态与半选态都由组件报出',-1)),o(r,{src:"tree/09-checkable"}),e[20]||(e[20]=d("h3",{id:"拖拽搬家",tabindex:"-1"},[t("拖拽搬家 "),d("a",{class:"header-anchor",href:"#拖拽搬家","aria-label":'Permalink to "拖拽搬家"'},"​")],-1)),e[21]||(e[21]=d("p",null,"整个节点都是拖动源：按住拖到别处松手，也可以 Tab 进树里用 Alt + 上下键在同层挪、Alt + 左右键改层级。三档落点（插在前 / 插在后 / 放进目录里）连同指示线、自我后代守卫与读屏播报都归库；树仍不拥有数据，宿主只管按库报的 value、parent、index 把数组搬一下，外加一条 allowDrop 说这次许不许",-1)),o(r,{src:"tree/10-drag-move"}),e[22]||(e[22]=d("h3",{id:"末端横排",tabindex:"-1"},[t("末端横排 "),d("a",{class:"header-anchor",href:"#末端横排","aria-label":'Permalink to "末端横排"'},"​")],-1)),e[23]||(e[23]=d("p",null,"leaf-orientation 按结构判据横排「子节点全是叶子」的那层；要指定哪一层横排就在节点上标 childrenOrientation，它比树级值优先，标 vertical 也压得住",-1)),o(r,{src:"tree/11-orientation"}),e[24]||(e[24]=d("h3",{id:"范围选",tabindex:"-1"},[t("范围选 "),d("a",{class:"header-anchor",href:"#范围选","aria-label":'Permalink to "范围选"'},"​")],-1)),e[25]||(e[25]=d("p",null,"按住 Shift 点某一项，选中锚点到它那一段；按可见序取，折叠起来的子节点选不进去",-1)),o(r,{src:"tree/12-range-selection"}),e[26]||(e[26]=a('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-tree&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhTreeBranch</code> <code>XhTreeBranchCheckbox</code> <code>XhTreeBranchContent</code> <code>XhTreeBranchControl</code> <code>XhTreeBranchIndicator</code> <code>XhTreeBranchText</code> <code>XhTreeBranchTrigger</code> <code>XhTreeItem</code> <code>XhTreeItemCheckbox</code> <code>XhTreeItemIndicator</code> <code>XhTreeItemText</code> <code>XhTreeLabel</code> <code>XhTreeLiveRegion</code> <code>XhTreeNodeDragTrigger</code> <code>XhTreeRoot</code> <code>XhTreeTree</code></td></tr><tr><td>组合式函数</td><td><code>useTree</code></td></tr><tr><td>状态机</td><td><code>treeMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/tree.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;tree&quot;</code>：<code>root</code> · <code>label</code> · <strong><code>tree</code></strong> · <strong><code>item</code></strong> · <code>item-checkbox</code> · <code>item-indicator</code> · <code>item-text</code> · <code>branch</code> · <code>branch-checkbox</code> · <code>branch-control</code> · <code>branch-trigger</code> · <code>branch-indicator</code> · <code>branch-text</code> · <code>branch-content</code> · <code>node-drag-trigger</code> · <code>live-region</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>collection</code></td><td><code>TreeNode[]</code></td><td></td><td>树数据，层级元信息的唯一事实源。缺省为空树。</td></tr><tr><td><code>leafOrientation</code></td><td><code>Orientation</code></td><td></td><td>末端那一层怎么排，默认 vertical（每行一个）。horizontal 让它们并排铺开。 只作用于「子节点全是叶子」的那一层——菜单授权里就是按钮那层： 一个菜单下十几个按钮，横排一行铺完，省掉纵向翻找。中间层与整棵树恒是竖排， 它们承载的是层级本身，横过来层级就读没了。 这是结构判据，逐层自动认。要精确指定哪一层横排，在节点上标 <code>childrenOrientation</code>，它比本项优先。 只管排布，不动键盘：方向键在树上是层级操作（左右收展、上下走可见行）， 这是 treeview 的规范语义，不随排布方向改写。</td></tr><tr><td><code>expandedValue</code></td><td><code>string[]</code></td><td></td><td>展开集合。给定即受控：cell 直读 prop，写只发 onExpandedChange 不落内部值。</td></tr><tr><td><code>defaultExpandedValue</code></td><td><code>string[]</code></td><td></td><td></td></tr><tr><td><code>selection</code></td><td><code>string[]</code></td><td></td><td>选中集合。给定即受控，语义同上。</td></tr><tr><td><code>defaultSelection</code></td><td><code>string[]</code></td><td></td><td></td></tr><tr><td><code>multiple</code></td><td><code>boolean</code></td><td></td><td>复选：点击与确认键都是「切换」，tree 带 aria-multiselectable=true。默认 false（单选）。</td></tr><tr><td><code>selectionMode</code></td><td><code>TreeSelectionMode</code></td><td></td><td>选择模式的旧写法，默认 single。 @deprecated 用 <code>multiple</code>。两者同时给时以 selectionMode 为准（与 listbox 同一条规矩）， 旧代码的行为因此一点不变。</td></tr><tr><td><code>cascade</code></td><td><code>boolean</code></td><td></td><td>multiple 下父子级联勾选：点分支整枝传导、子全勾父勾、部分勾中半选， 禁用子树整棵冻结。默认 false（朴素切换）；single 下无效。</td></tr><tr><td><code>checkedStrategy</code></td><td><code>CascadeStrategy</code></td><td></td><td>级联下对外值的收敛策略，默认 child（只收叶）；parent = 最高整枝，all = 全部勾中节点。</td></tr><tr><td><code>expandOnClick</code></td><td><code>boolean</code></td><td></td><td>点分支行是否顺带展开/收起，默认 true。关掉后只有 branch-trigger 与左右方向键能改展开态。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>整棵树禁用：所有节点转 aria-disabled，键盘与点击都不再改展开/选中。</td></tr><tr><td><code>loop</code></td><td><code>boolean</code></td><td></td><td>上下键走到首尾是否回绕，默认 false。</td></tr><tr><td><code>typeahead</code></td><td><code>boolean</code></td><td></td><td>连打检索，默认开。关掉后可打印字符一律放行给页面。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，默认 ltr；只对调左右方向键的「展开/收起」语义。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;TreeTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>nodeDraggable</code></td><td><code>boolean</code></td><td></td><td>节点可以拖着搬家。整个节点都是拖动源，不另出把手。</td></tr><tr><td><code>allowDrop</code></td><td><code>(move: TreeMove) =&gt; boolean</code></td><td></td><td>这一次搬家许不许。收到的是折算好的落点（搬到哪个父下面的第几位）。 不给即都许——「落进自己的后代」与「落在禁用节点上」两条库自己会拦。</td></tr><tr><td><code>onNodeMove</code></td><td><code>(move: TreeMove) =&gt; void</code></td><td></td><td></td></tr><tr><td><code>onExpandedChange</code></td><td><code>(details: TreeExpandedChangeDetails) =&gt; void</code></td><td></td><td></td></tr><tr><td><code>onSelectionChange</code></td><td><code>(details: TreeSelectionChangeDetails) =&gt; void</code></td><td></td><td></td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>expanded-change</code></td><td><code>TreeExpandedChangeDetails</code></td><td>展开集合变化；detail 为 <code>{ value: string[] }</code></td></tr><tr><td><code>selection-change</code></td><td><code>TreeSelectionChangeDetails</code></td><td>选中集合变化；detail 为 <code>{ value: string[] }</code></td></tr><tr><td><code>node-move</code></td><td><code>TreeNodeMoveDetails</code></td><td>节点搬了家；detail 为 <code>{ value, parent, index }</code>，parent 为 null 即根层，index 是在那一层的落位（已算过先摘后插）</td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhTreeRoot</code></td><td><code>default</code></td><td><code>TreeRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>EXPANDED.SET</code> · <code>BRANCH.EXPAND</code> · <code>BRANCH.COLLAPSE</code> · <code>BRANCH.TOGGLE</code> · <code>SELECTION.SET</code> · <code>NODE.SELECT</code> · <code>NODE.FOCUS</code> · <code>TREE.BLUR</code> · <code>NODE_DRAG.START</code> · <code>NODE_DRAG.MOVE</code> · <code>NODE_DRAG.END</code> · <code>NODE_DRAG.CANCEL</code> · <code>NODE.MOVE_BY</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useTree</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>collection</code></td><td><code>readonly TreeNode[]</code></td><td>作者给的原始树数据。</td></tr><tr><td><code>visibleNodes</code></td><td><code>readonly TreeVisibleNode[]</code></td><td>当前可见行序列（收起分支的子树不在其中）。 方向键、Home/End 与连打检索都在它上面走，不是在原始树上走。</td></tr><tr><td><code>dropTarget</code></td><td><code>DropTarget | null</code></td><td>此刻的落点；松手就落在这儿。不合法或没落在任何节点上时是 null。</td></tr><tr><td><code>announcement</code></td><td><code>string</code></td><td>读屏播报文本。渲进 live-region，不进视觉版面。</td></tr><tr><td><code>expandedValue</code></td><td><code>string[]</code></td><td></td></tr><tr><td><code>selection</code></td><td><code>string[]</code></td><td></td></tr><tr><td><code>focusedValue</code></td><td><code>string | null</code></td><td>焦点锚点；焦点不在树内、或它已被收起而不可见时为 null。</td></tr><tr><td><code>multiple</code></td><td><code>boolean</code></td><td>生效的是不是复选。</td></tr><tr><td><code>selectionMode</code></td><td><code>TreeSelectionMode</code></td><td>@deprecated 读 <code>multiple</code>。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>isExpanded</code></td><td><code>(value: string) =&gt; boolean</code></td><td></td></tr><tr><td><code>isSelected</code></td><td><code>(value: string) =&gt; boolean</code></td><td></td></tr><tr><td><code>isIndeterminate</code></td><td><code>(value: string) =&gt; boolean</code></td><td>级联模式下该分支是否半选（有效叶后代有勾有不勾）；非级联恒 false。</td></tr><tr><td><code>setExpandedValue</code></td><td><code>(next: string[]) =&gt; void</code></td><td></td></tr><tr><td><code>setSelection</code></td><td><code>(next: string[]) =&gt; void</code></td><td></td></tr><tr><td><code>expand</code></td><td><code>(value: string) =&gt; void</code></td><td></td></tr><tr><td><code>collapse</code></td><td><code>(value: string) =&gt; void</code></td><td></td></tr><tr><td><code>select</code></td><td><code>(value: string, options?: { extend?: boolean }) =&gt; void</code></td><td>选中某个节点。extend 为真时选中锚点到这一节点那一段（仅复选、且非级联）。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTreeProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getNodeDragTriggerProps</code></td><td><code>(props: TreeNodeProps) =&gt; T[&#39;element&#39;]</code></td><td>节点拖动把手。触屏那一路唯一的入口，不占 Tab 位。 常挂即可：nodeDraggable 关着或这个节点禁用时它自报 data-disabled、也不再让出滚动， 渲了不会错。按拖不拖得动来决定渲不渲，会让 DOM 结构随状态变。</td></tr><tr><td><code>getLiveRegionProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: TreeNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemTextProps</code></td><td><code>(props: TreeNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemCheckboxProps</code></td><td><code>(props: TreeNodeProps) =&gt; T[&#39;element&#39;]</code></td><td>勾选把手：把「勾这一项」与「点这一行」分成两个可点区域，不给它就没有独立把手。</td></tr><tr><td><code>getItemIndicatorProps</code></td><td><code>(props: TreeNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBranchProps</code></td><td><code>(props: TreeNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBranchCheckboxProps</code></td><td><code>(props: TreeNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBranchControlProps</code></td><td><code>(props: TreeNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBranchTriggerProps</code></td><td><code>(props: TreeNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBranchIndicatorProps</code></td><td><code>(props: TreeNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBranchTextProps</code></td><td><code>(props: TreeNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getBranchContentProps</code></td><td><code>(props: TreeNodeProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/treeview/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focus outside the tree</td><td>整棵树只占一个 Tab 位：焦点进入锚点节点，无锚点时先落容器再由它转投</td></tr><tr><td><code>ArrowDown</code></td><td>focus in tree</td><td>焦点移到下一个可见行（禁用行跳过；loop 默认关，末行不回绕）</td></tr><tr><td><code>ArrowUp</code></td><td>focus in tree</td><td>焦点移到上一个可见行（禁用行跳过；loop 默认关，首行不回绕）</td></tr><tr><td><code>Home</code></td><td>focus in tree</td><td>焦点移到首个可见行</td></tr><tr><td><code>End</code></td><td>focus in tree</td><td>焦点移到末个可见行（展开着的子树也算行）</td></tr><tr><td><code>ArrowRight</code></td><td>focus on branch（dir=rtl 时改由 ArrowLeft 承担）</td><td>收起的分支就地展开；已展开则把焦点移到首个子节点；叶子上什么都不做且不吞键</td></tr><tr><td><code>ArrowLeft</code></td><td>focus in tree（dir=rtl 时改由 ArrowRight 承担）</td><td>展开的分支就地收起；收起的分支与叶子则把焦点移到父节点；根层的行什么都不做</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus on node, 节点未禁用</td><td>选中焦点节点（单选替换、复选切换）；焦点在分支上且 expandOnClick 未关时顺带切换展开态</td></tr><tr><td><code>*</code></td><td>focus in tree</td><td>展开与焦点行同一父级的全部分支（已展开与禁用的不动）；同级没有可展开的分支时不吞这个键</td></tr><tr><td><code>单个可打印字符</code></td><td>focus in tree, typeahead 未关</td><td>连打检索在可见行上按 label 首字母搬焦点，不改选中值，也不展开任何分支</td></tr><tr><td><code>Alt+ArrowUp</code> / <code>Alt+ArrowDown</code></td><td>focus in tree, draggable 开着</td><td>把焦点节点在同一层的兄弟里往前 / 往后挪一位，按一下就是一次完整提交，不进拖动态；纵轴与文字方向无关，rtl 下两键不对调；已是同层首位 / 末位就不动，也不回绕；落点节点禁用或 allowDrop 不许就不搬。裸方向键仍是走可见行、确认键仍是选中</td></tr><tr><td><code>Alt+ArrowLeft</code> / <code>Alt+ArrowRight</code></td><td>focus in tree, draggable 开着</td><td>改焦点节点的缩进层级：往里去是认上一个兄弟当父、落进它子层末位，往外去是变成父节点的下一个兄弟；rtl 下两键对调，「往里去」的那个方向恒是缩进。没有上一个兄弟就缩不进去，已在根层就退不出去，两种情形都不动；落点节点禁用或 allowDrop 不许就不搬</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>tree</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>tree</code></td><td><code>aria-labelledby</code></td><td><code>label</code> 部件的 id</td></tr><tr><td><code>tree</code></td><td><code>aria-multiselectable</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>tree</code></td><td><code>aria-orientation</code></td><td>&#39;vertical&#39;</td></tr><tr><td><code>tree</code></td><td><code>role</code></td><td>&#39;tree&#39;</td></tr><tr><td><code>item-checkbox</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>item-indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>branch</code></td><td><code>aria-expanded</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>branch</code></td><td><code>aria-label</code></td><td>metaOf(node.value)?.label</td></tr><tr><td><code>branch-checkbox</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>branch-trigger</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>branch-indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>branch-content</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr><tr><td><code>node-drag-trigger</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>live-region</code></td><td><code>aria-atomic</code></td><td>&#39;true&#39;</td></tr><tr><td><code>live-region</code></td><td><code>aria-live</code></td><td>&#39;polite&#39;</td></tr><tr><td><code>live-region</code></td><td><code>role</code></td><td>&#39;status&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/tree.css</code> 按部件选择：<code>[data-scope=&quot;tree&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>&#39;vertical&#39;</td></tr><tr><td><code>label</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>tree</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>tree</code></td><td><code>data-orientation</code></td><td>&#39;vertical&#39;</td></tr><tr><td><code>item</code></td><td><code>data-draggable</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item</code></td><td><code>data-drop</code></td><td>&#39;before&#39; | &#39;after&#39; | &#39;inside&#39;</td></tr><tr><td><code>branch-control</code></td><td><code>data-draggable</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>branch-control</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>branch-control</code></td><td><code>data-drop</code></td><td>&#39;before&#39; | &#39;after&#39; | &#39;inside&#39;</td></tr><tr><td><code>branch-content</code></td><td><code>data-orientation</code></td><td>&#39;horizontal&#39; | &#39;vertical&#39;</td></tr><tr><td><code>node-drag-trigger</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>node-drag-trigger</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-tree-bg</code> · <code>--xh-tree-border</code> · <code>--xh-tree-branch-content-gap</code> · <code>--xh-tree-branch-gap</code> · <code>--xh-tree-branch-indicator-fg</code> · <code>--xh-tree-checkbox-bg</code> · <code>--xh-tree-checkbox-bg-checked</code> · <code>--xh-tree-checkbox-border</code> · <code>--xh-tree-checkbox-border-checked</code> · <code>--xh-tree-checkbox-border-disabled</code> · <code>--xh-tree-checkbox-fg</code> · <code>--xh-tree-checkbox-radius</code> · <code>--xh-tree-checkbox-size</code> · <code>--xh-tree-drag-fg</code> · <code>--xh-tree-drag-fg-active</code> · <code>--xh-tree-drag-fg-disabled</code> · <code>--xh-tree-drag-grip-long</code> · <code>--xh-tree-drag-grip-short</code> · <code>--xh-tree-drag-radius</code> · <code>--xh-tree-drag-size</code> · <code>--xh-tree-dragging-opacity</code> · <code>--xh-tree-drop-fg</code> · <code>--xh-tree-drop-inside-bg</code> · <code>--xh-tree-drop-line</code> · <code>--xh-tree-fg</code> · <code>--xh-tree-gap</code> · <code>--xh-tree-icon-size</code> · <code>--xh-tree-indent</code> · <code>--xh-tree-indicator-fg</code> · <code>--xh-tree-indicator-size</code> · <code>--xh-tree-label-fg</code> · <code>--xh-tree-label-font-size</code> · <code>--xh-tree-label-font-weight</code> · <code>--xh-tree-leaf-row-gap</code> · <code>--xh-tree-max-h</code> · <code>--xh-tree-px</code> · <code>--xh-tree-py</code> · <code>--xh-tree-radius</code> · <code>--xh-tree-row-bg-hover</code> · <code>--xh-tree-row-fg</code> · <code>--xh-tree-row-fg-selected</code> · <code>--xh-tree-row-font-size</code> · <code>--xh-tree-row-gap</code> · <code>--xh-tree-row-leading</code> · <code>--xh-tree-row-px</code> · <code>--xh-tree-row-py</code> · <code>--xh-tree-row-radius</code> · <code>--xh-tree-row-selected-font-weight</code> · <code>--xh-tree-tree-gap</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像；另有按 <code>dir</code> 分支的规则。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>前缀放<a href="./icon">图标</a>，行尾放<a href="./menu">菜单</a>；放进<a href="./splitter">分栏</a>的一侧。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>大树一定要虚拟化或按需加载，一次展开全部会卡住。</li><li>级联勾选的策略要与后端约定一致。</li><li>只想让某一层横排就标 <code>childrenOrientation</code>，别开树级 <code>leafOrientation</code>： 后者认结构，别处凑巧「子节点全是叶子」的层也会跟着横过来，还会随数据增减变来变去。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>展开状态不持久：用户每次进来都要重新展开一路。</li><li>拖放换父没有落点提示。</li></ul>',45))])}const k=i(s,[["render",p]]);export{P as __pageData,k as default};
